<?php require __DIR__.'/_layout_start.php'; ?><div class="toolbar"><div><h1><?= (int)$event['id']?'Modifica evento':'Nuovo evento' ?></h1></div><a href="/admin/campus/events">Torna agli eventi</a></div><?php foreach($errors as $err):?><div class="error"><?= htmlspecialchars($err,ENT_QUOTES,'UTF-8') ?></div><?php endforeach;?><form method="post" action="/admin/campus/events/save" class="panel"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf,ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int)$event['id'] ?>"><div class="formgrid"><label>Titolo<input name="title" required value="<?= htmlspecialchars((string)$event['title'],ENT_QUOTES,'UTF-8') ?>"></label><label>Slug<input name="slug" value="<?= htmlspecialchars((string)$event['slug'],ENT_QUOTES,'UTF-8') ?>"></label><label>Audience<select name="audience"><option value="public" <?= $event['audience']==='public'?'selected':'' ?>>Pubblico</option><option value="cat" <?= $event['audience']==='cat'?'selected':'' ?>>CAT</option></select></label><label>Luogo<input name="location" value="<?= htmlspecialchars((string)$event['location'],ENT_QUOTES,'UTF-8') ?>"></label><label class="full">Indirizzo<input name="address" value="<?= htmlspecialchars((string)$event['address'],ENT_QUOTES,'UTF-8') ?>"></label><label>Inizio<input type="datetime-local" name="starts_at" required value="<?= !empty($event['starts_at'])?htmlspecialchars(str_replace(' ','T',substr((string)$event['starts_at'],0,16)),ENT_QUOTES,'UTF-8'):'' ?>"></label><label>Fine<input type="datetime-local" name="ends_at" value="<?= !empty($event['ends_at'])?htmlspecialchars(str_replace(' ','T',substr((string)$event['ends_at'],0,16)),ENT_QUOTES,'UTF-8'):'' ?>"></label><label>Posti massimi<input type="number" min="1" name="max_seats" value="<?= htmlspecialchars((string)$event['max_seats'],ENT_QUOTES,'UTF-8') ?>"></label><label>Scadenza iscrizioni<input type="datetime-local" name="registration_deadline" value="<?= !empty($event['registration_deadline'])?htmlspecialchars(str_replace(' ','T',substr((string)$event['registration_deadline'],0,16)),ENT_QUOTES,'UTF-8'):'' ?>"></label><label class="full">Descrizione breve<textarea name="short_description"><?= htmlspecialchars((string)$event['short_description'],ENT_QUOTES,'UTF-8') ?></textarea></label><label class="full">Descrizione<textarea name="description" rows="8"><?= htmlspecialchars((string)$event['description'],ENT_QUOTES,'UTF-8') ?></textarea></label><label>Ordine<input type="number" name="sort_order" value="<?= (int)$event['sort_order'] ?>"></label><label class="check"><input type="checkbox" name="registration_open" value="1" <?= (int)$event['registration_open']?'checked':'' ?>> Iscrizioni aperte</label><label class="check"><input type="checkbox" name="published" value="1" <?= (int)$event['published']?'checked':'' ?>> Pubblicato</label><label class="check"><input type="checkbox" name="cancelled" value="1" <?= (int)$event['cancelled']?'checked':'' ?>> Annullato</label></div><button class="btn" type="submit" style="margin-top:18px">Salva evento</button></form><?php require __DIR__.'/_layout_end.php'; ?>
